            if wall is not None and nr == wall - 1:
                for k in range(1, h):
                    rr = nr - k
                    if rr < 0:
                        break
                    for cc in (c-k, c+k):
                        if 0 <= cc < w:
                            out[rr][cc] = 4
    return out
'''
